                $stmt->send_long_data(16,$signature['data']);
                if ($stmt->execute()) { $newId=(int)$conn->insert_id; $stmt->close(); $notifyStage($conn,'Supervisor Review',$newId,$title); $notice='Request submitted for supervisor/operations review.'; }
