<section><h2>Requests and approval status</h2><div class="aer-table-wrap"><table class="aer-table"><thead><tr><th>Reference</th><th>Request</th><th>Project/program</th><th>Activity & milestone</th><th>Amount</th><th>Status</th><th>Requester / date</th><th>Review</th></tr></thead><tbody><?php if(!$requestRows):?><tr><td colspan="8">No requests found.</td></tr><?php endif;?><?php foreach($requestRows as $r):?><tr><td><?=aer_h($r['reference_code'])?></td><td><strong><?=aer_h($r['title'])?></strong> <button type="button" class="aer-secondary" data-open-modal="request-details-<?=$r['request_id']?>">Details</button><dialog class="aer-dialog aer-record-dialog" id="request-details-<?=$r['request_id']?>"><div class="aer-dialog-head"><h2><?=aer_h($r['title'])?></h2><button type="button" data-close-modal>Close</button></div><p><?=nl2br(aer_h($r['concept']))?></p><?php if(!empty($r['requester_signature'])):?><p>Requester signature<br><img class="aer-signed-image" alt="Requester signature" src="data:<?=aer_h($r['requester_signature_mime']??'image/png')?>;base64,<?=base64_encode($r['requester_signature'])?>"></p><?php endif;?><?php if($signatureSchemaReady):?><?php $timeline=$conn->prepare('SELECT stage,action,comments,reviewed_at,signature_data,signature_mime FROM activity_event_request_reviews WHERE request_id=? ORDER BY reviewed_at');$timeline->bind_param('i',$r['request_id']);$timeline->execute();$logs=$timeline->get_result();while($log=$logs->fetch_assoc()):?><p><small><?=aer_h($log['stage'])?>: <?=aer_h($log['action'])?><?=($log['comments']??'')!==''?' — '.aer_h($log['comments']):''?> (<?=aer_h($log['reviewed_at'])?>)</small></p><?php if(!empty($log['signature_data'])):?><img class="aer-signed-image" alt="<?=aer_h($log['stage'])?> reviewer signature" src="data:<?=aer_h($log['signature_mime']??'image/png')?>;base64,<?=base64_encode($log['signature_data'])?>"><?php endif;?><?php endwhile;$timeline->close();?><?php endif;?></dialog></td><td><?=aer_h($r['entity_type'])?> #<?=$r['entity_id']?></td><td><?=aer_h($r['activity_name'])?><br><small><?=aer_h($r['milestone_name']??'Milestone')?></small></td><td><?=aer_h($r['currency'])?> <?=number_format((float)$r['requested_amount'],2)?></td><td><span class="aer-status"><?=aer_h($r['status'])?></span></td><td><?=aer_h($r['requester']??'Staff')?><br><small><?=aer_h($r['created_at'])?></small></td><td><?php $stageRoles=['Supervisor Review'=>$ops,'Procurement Review'=>$procurement,'Finance Review'=>$finance,'Director Approval'=>$director];if(!empty($stageRoles[$r['status']])):?><button type="button" class="aer-button" data-open-modal="request-review-<?=$r['request_id']?>">Review</button><dialog class="aer-dialog aer-review-dialog" id="request-review-<?=$r['request_id']?>"><div class="aer-dialog-head"><h2>Review <?=aer_h($r['reference_code'])?></h2><button type="button" data-close-modal>Close</button></div><form method="post" class="aer-review-form" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=aer_h($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="review"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><textarea name="comments" placeholder="Comments (required for return/rejection)"></textarea><div class="aer-signature-box"><strong>Reviewer signature (required)</strong><span>Draw your signature or upload PNG/JPEG (max 2 MB).</span><canvas class="aer-signature-canvas" width="440" height="130" aria-label="Draw reviewer signature"></canvas><input type="hidden" name="signature_data"><div class="aer-signature-tools"><button type="button" class="aer-secondary aer-clear-signature">Clear signature</button><label>Upload signature<input type="file" name="signature_file" accept="image/png,image/jpeg"></label></div></div><button name="decision" value="Approved">Approve</button><button class="aer-secondary" name="decision" value="Returned">Return</button><button class="aer-secondary" name="decision" value="Rejected">Reject</button></form></dialog><?php endif;?><?php if((!empty($stageRoles[$r['status']])||(int)$r['created_by']===$uid)&&in_array($r['status'],['Supervisor Review','Procurement Review','Finance Review','Director Approval'],true)):?><form method="post" class="aer-inline"><input type="hidden" name="csrf_token" value="<?=aer_h($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="remind"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><button type="submit" class="aer-secondary">Send reminder</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<script>
const entityType=document.getElementById('entityType'),entityId=document.getElementById('entityId'),milestone=document.getElementById('milestoneId');
function filterLinks(){const type=entityType.value,id=entityId.value;for(const o of entityId.options)if(o.value)o.hidden=o.dataset.type!==type;for(const o of milestone.options)if(o.value)o.hidden=o.dataset.type!==type||(id&&o.dataset.entity!==id);}
entityType.addEventListener('change',filterLinks);entityId.addEventListener('change',filterLinks);filterLinks();
</script>
<script>
const activitySearch=document.getElementById('activitySearch'),activitySelect=document.getElementById('activitySelect');
function filterActivities(){const milestoneId=milestone.value,query=activitySearch.value.trim().toLowerCase();let found=0;for(const option of activitySelect.options){if(!option.value)continue;const visible=option.dataset.milestone===milestoneId&&option.text.toLowerCase().includes(query);option.hidden=!visible;if(visible)found++;}activitySelect.value='';activitySelect.options[0].text=milestoneId?(found?'Choose activity':'No activities match this milestone/search'):'Select a milestone first';}
milestone.addEventListener('change',()=>{filterActivities();activitySearch.value='';filterActivities();});activitySearch.addEventListener('input',filterActivities);filterActivities();
entityType.addEventListener('change',()=>{entityId.value='';milestone.value='';activitySearch.value='';filterLinks();filterActivities();});entityId.addEventListener('change',()=>{milestone.value='';activitySearch.value='';filterActivities();});
const requestForm=document.getElementById('requestForm'),panels=[...requestForm.querySelectorAll('[data-panel]')],tabs=[...requestForm.querySelectorAll('[role="tab"]')],amountDisplay=document.getElementById('amountDisplay'),requestedAmount=document.getElementById('requestedAmount');let activeStep=0;
function showStep(step){activeStep=Math.max(0,Math.min(2,step));panels.forEach((panel,index)=>panel.hidden=index!==activeStep);tabs.forEach((tab,index)=>tab.setAttribute('aria-selected',index===activeStep?'true':'false'));const focus=panels[activeStep].querySelector('input,select,textarea');if(focus)focus.focus();}
function validStep(step){for(const control of panels[step].querySelectorAll('input,select,textarea'))if(!control.checkValidity()){showStep(step);control.reportValidity();return false;}return true;}
tabs.forEach((tab,index)=>tab.addEventListener('click',()=>{if(index<=activeStep||validStep(activeStep))showStep(index);}));requestForm.querySelectorAll('[data-next]').forEach(button=>button.addEventListener('click',()=>{if(validStep(activeStep))showStep(activeStep+1);}));requestForm.querySelectorAll('[data-back]').forEach(button=>button.addEventListener('click',()=>showStep(activeStep-1)));
function cleanAmount(){let raw=amountDisplay.value.replace(/,/g,'').replace(/[^0-9.]/g,'');const dot=raw.indexOf('.');if(dot!==-1)raw=raw.slice(0,dot+1)+raw.slice(dot+1).replace(/\./g,'');requestedAmount.value=raw;return raw;}
amountDisplay.addEventListener('input',()=>{amountDisplay.setCustomValidity('');cleanAmount();});amountDisplay.addEventListener('blur',()=>{const raw=cleanAmount();if(raw&&Number.isFinite(Number(raw))){const [whole,decimal]=raw.split('.');amountDisplay.value=Number(whole||'0').toLocaleString('en-US')+(decimal!==undefined?'.'+decimal:'');}});
requestForm.addEventListener('submit',event=>{cleanAmount();for(let step=0;step<panels.length;step++){for(const control of panels[step].querySelectorAll('input,select,textarea'))if(!control.checkValidity()){event.preventDefault();showStep(step);control.reportValidity();return;}}const signaturePad=requestForm.querySelector('[name="signature_data"]'),signatureFile=requestForm.querySelector('[name="signature_file"]');if(!signaturePad.value&&!signatureFile.files.length){event.preventDefault();showStep(2);alert('Draw or upload your signature before submitting.');return;}if(!requestedAmount.value||Number(requestedAmount.value)<=0){event.preventDefault();showStep(1);amountDisplay.setCustomValidity('Enter an amount greater than zero.');amountDisplay.reportValidity();return;}amountDisplay.setCustomValidity('');});
document.querySelectorAll('.aer-signature-canvas').forEach(canvas=>{const form=canvas.closest('form'),signature=form.querySelector('[name="signature_data"]'),context=canvas.getContext('2d');let drawing=false;context.lineWidth=2.5;context.lineCap='round';context.strokeStyle='#111827';function point(event){const rect=canvas.getBoundingClientRect();return{x:(event.clientX-rect.left)*canvas.width/rect.width,y:(event.clientY-rect.top)*canvas.height/rect.height};}canvas.addEventListener('pointerdown',event=>{drawing=true;canvas.setPointerCapture(event.pointerId);const p=point(event);context.beginPath();context.moveTo(p.x,p.y);});canvas.addEventListener('pointermove',event=>{if(!drawing)return;const p=point(event);context.lineTo(p.x,p.y);context.stroke();});canvas.addEventListener('pointerup',()=>{if(!drawing)return;drawing=false;signature.value=canvas.toDataURL('image/png');});canvas.addEventListener('pointercancel',()=>{drawing=false;});form.querySelector('.aer-clear-signature').addEventListener('click',()=>{context.clearRect(0,0,canvas.width,canvas.height);signature.value='';});});
document.querySelectorAll('.aer-review-form').forEach(form=>form.addEventListener('submit',event=>{const signature=form.querySelector('[name="signature_data"]'),file=form.querySelector('[name="signature_file"]');if(!signature.value&&!file.files.length){event.preventDefault();alert('Draw or upload your signature before reviewing this request.');}}));
document.addEventListener('click',event=>{const openButton=event.target.closest('[data-open-modal]'),closeButton=event.target.closest('[data-close-modal]');if(openButton){document.getElementById(openButton.dataset.openModal)?.showModal();}if(closeButton){closeButton.closest('dialog')?.close();}});
const requestModal=document.getElementById('requestModal');document.getElementById('openRequestModal').addEventListener('click',()=>requestModal.showModal());document.getElementById('closeRequestModal').addEventListener('click',()=>requestModal.close());document.getElementById('cancelRequestModal').addEventListener('click',()=>requestModal.close());
</script>
</div><?php $stmt->close(); require_once __DIR__ . '/includes/footer.php'; ?>
